class Solution {
    long ipToInt(const string& ip) {
        long ans = 0;
        stringstream ss(ip);
        string token;
        while (getline(ss, token, '.')) {
            ans = (ans << 8) + stoi(token);
        }
        return ans;
    }
    string intToIp(long val) {
        return to_string((val >> 24) & 255) + "." +
               to_string((val >> 16) & 255) + "." +
               to_string((val >> 8) & 255) + "." +
               to_string(val & 255);
    }
public:
    vector<string> ipToCIDR(string ip, int n) {
        long cur = ipToInt(ip);
        vector<string> res;
        while (n > 0) {
            long lowbit = (cur > 0) ? (cur & -cur) : (1L << 32);
            while (lowbit > n) lowbit /= 2;
            int len = 0;
            long tmp = lowbit;
            while (tmp > 1) { len++; tmp /= 2; }
            int mask = 32 - len;
            res.push_back(intToIp(cur) + "/" + to_string(mask));
            cur += lowbit;
            n -= lowbit;
        }
        return res;
    }
};

class Solution {
    public List<String> ipToCIDR(String ip, int n) {
        long cur = ipToInt(ip);
        List<String> res = new ArrayList<>();
        while (n > 0) {
            long lowbit = (cur > 0) ? (cur & -cur) : (1L << 32);
            while (lowbit > n) lowbit /= 2;
            int len = Long.numberOfTrailingZeros(lowbit);
            int mask = 32 - len;
            res.add(intToIp(cur) + "/" + mask);
            cur += lowbit;
            n -= (int) lowbit;
        }
        return res;
    }
    private long ipToInt(String ip) {
        long ans = 0;
        for (String octet : ip.split("\\.")) {
            ans = (ans << 8) + Long.parseLong(octet);
        }
        return ans;
    }
    private String intToIp(long val) {
        return ((val >> 24) & 255) + "." + ((val >> 16) & 255) + "." + ((val >> 8) & 255) + "." + (val & 255);
    }
}

var ipToCIDR = function(ip, n) {
    function ipToInt(s) {
        return s.split('.').reduce((acc, octet) => (acc * 256) + Number(octet), 0);
    }
    function intToIp(val) {
        return [
            (val >>> 24) & 255,
            (val >>> 16) & 255,
            (val >>> 8) & 255,
            val & 255
        ].join('.');
    }
    let cur = ipToInt(ip);
    const res = [];
    while (n > 0) {
        let lowbit = (cur > 0) ? (cur & -cur) : 0x100000000;
        while (lowbit > n) lowbit = Math.floor(lowbit / 2);
        const len = Math.log2(lowbit);
        const mask = 32 - len;
        res.push(`${intToIp(cur)}/${mask}`);
        cur += lowbit;
        n -= lowbit;
    }
    return res;
};
